"""Cellwise fill and blank-down transforms."""
import csv
import sys


def run(command, argv):
    delim = ','; out = '-'; no = False; selection = None; value = None; redact = ''
    path = '-'; i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('-h', '--help'):
            print('Fill empty cells or blank consecutive identical values. Usage: xan ' + command + ' [options] [<input>]')
            return 0
        if a in ('-n', '--no-headers'): no = True
        elif a in ('-d', '--delimiter', '-o', '--output', '-s', '--select', '-v', '--value', '-r', '--redact'):
            i += 1
            if i >= len(argv): raise ValueError('missing argument for ' + a)
            v = argv[i]
            if a in ('-d', '--delimiter'): delim = v
            elif a in ('-o', '--output'): out = v
            elif a in ('-s', '--select'): selection = v
            elif a in ('-v', '--value'): value = v
            else: redact = v
        elif a.startswith('-') and a != '-': raise ValueError('unknown option: ' + a)
        elif path == '-': path = a
        else: raise ValueError('unexpected argument: ' + a)
        i += 1
    f = open(path, 'r', encoding='utf-8-sig', newline='') if path != '-' else sys.stdin
    try: records = list(csv.reader(f, delimiter=delim))
    finally:
        if f is not sys.stdin: f.close()
    header = None if no else (records.pop(0) if records else [])
    width = len(header) if header is not None else max((len(r) for r in records), default=0)
    names = header if header is not None else [str(j) for j in range(width)]
    indices = list(range(width))
    if selection:
        indices = []
        for token in selection.split(','):
            token = token.strip()
            if ':' in token:
                left,right=token.split(':',1)
                def ind(t,default):
                    if not t:return default
                    try:
                        j=int(t); return j+width if j<0 else j
                    except ValueError:return names.index(t)
                lo,hi=ind(left,0),ind(right,width-1)
                indices.extend(range(lo,hi+1) if lo<=hi else range(lo,hi-1,-1))
            else:
                try: j=int(token); j=j+width if j<0 else j
                except ValueError: j=names.index(token)
                indices.append(j)
    records = [r + [''] * max(0, width-len(r)) for r in records]
    if command == 'fill':
        last = [''] * width
        for row in records:
            for j in indices:
                if row[j]: last[j] = row[j]
                elif value is not None: row[j] = value
                elif last[j]: row[j] = last[j]
    else:
        previous = [None] * width
        for row in records:
            for j in indices:
                if previous[j] is not None and row[j] == previous[j]: row[j] = redact
                else: previous[j] = row[j]
    g = sys.stdout if out == '-' else open(out, 'w', encoding='utf-8', newline='')
    w = csv.writer(g, delimiter=delim, lineterminator='\n')
    if header is not None: w.writerow(header)
    w.writerows(records)
    if g is not sys.stdout: g.close()
    return 0
